public void new()
{
    rentalListInternal = new List(Types::Class);
}

[SysAppCollection(classStr(FMAllReservationListItem), "Reservation list")]
public List rentalList(List _value=rentalListInternal)
{
    rentalListInternal = _value;
    return rentalListInternal;
}

public static FMAllReservationListPage getAllReservations(SysAppEntityContext _entityContext, List _filterContextList)
{
    FMRental rentalTable;
    FMCustomer customerTable;
    FMAddressTable addressTable;
    FMVehicle vehicleTable;
    FMAllReservationListPage rentalListPage = new FMAllReservationListPage();

    while select * from rentalTable
        join customerTable
        join vehicleTable
        join addressTable
        order by rentalTable.RentalId desc
        where rentalTable.Customer == customerTable.RecId
            && rentalTable.Vehicle == vehicleTable.RecId   
            && customerTable.AddressID == addressTable.RecId         
    {
        FMAllReservationListItem reservationListItem = new FMAllReservationListItem();
        reservationListItem.populate(rentalTable);

        reservationListItem.customer(new FMCustomerRefGroup());
        reservationListItem.customer().populate(customerTable);

        reservationListItem.vehicle(new FMVehicleRefGroup());
        reservationListItem.vehicle().populate(vehicleTable);

        rentalListPage.rentalList().addEnd(reservationListItem);
    }

    return rentalListPage;
}
